const input = $json.body || {};
const escapeHtml = (value) => String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').split(String.fromCharCode(34)).join('&quot;').replace(/'/g, '&#39;');
const email = String(input.email || '').trim().toLowerCase();
const username = escapeHtml(input.username);
const fullName = escapeHtml(input.full_name || input.username || 'there');
if (!email || !email.includes('@')) throw new Error('A valid account email is required');
const changedAt = new Date(input.changed_at || Date.now());
const changedAtSaudi = new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Riyadh',year:'numeric',month:'long',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit',hour12:true,timeZoneName:'short'}).format(changedAt);
const logoUrl = 'https://raw.githubusercontent.com/MaouXsama/n8n-it-support/main/dashboard/assets/masar-email-logo.png';
const html = `<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'></head><body style='margin:0;padding:0;background:#eef3f9;font-family:Arial,Helvetica,sans-serif;color:#10233f;'><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='width:100%;background:#eef3f9;padding:32px 14px;'><tr><td align='center'><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='width:100%;max-width:640px;background:#ffffff;border:1px solid #d8e2ef;border-radius:20px;overflow:hidden;box-shadow:0 10px 30px rgba(16,35,63,.08);'><tr><td style='height:5px;background:#10bfea;font-size:0;line-height:0;'>&nbsp;</td></tr><tr><td style='padding:24px 30px;background:#09234b;color:#ffffff;'><table role='presentation' width='100%' cellspacing='0' cellpadding='0'><tr><td width='86' valign='middle' style='width:86px;'><img src='${logoUrl}' width='72' height='72' alt='Masar' style='display:block;width:72px;height:72px;border-radius:15px;border:1px solid #149bc1;'></td><td valign='middle' style='padding-left:16px;'><div style='font-size:11px;font-weight:700;letter-spacing:2.2px;color:#86def2;margin-bottom:8px;'>MASAR SECURITY NOTICE</div><h1 style='margin:0;font-size:27px;line-height:1.2;color:#ffffff;'>Your password was changed</h1><div style='width:42px;height:3px;background:#ff9d1d;border-radius:3px;margin-top:13px;'></div></td></tr></table></td></tr><tr><td style='padding:32px 30px 28px;'><p style='margin:0 0 16px;font-size:18px;line-height:1.6;color:#10233f;'>Hello <strong>${fullName}</strong>,</p><p style='margin:0 0 24px;color:#53657d;font-size:15px;line-height:1.75;'>The password for your Masar IT Support account was changed successfully.</p><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='width:100%;margin:0 0 24px;background:#f6f9fc;border:1px solid #dce6f1;border-radius:14px;'><tr><td style='padding:20px 22px;border-left:4px solid #119dc0;'><div style='font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1.5px;color:#667890;margin-bottom:12px;'>Change details</div><table role='presentation' cellspacing='0' cellpadding='0' style='font-size:14px;line-height:1.8;color:#253a56;'><tr><td style='padding-right:14px;font-weight:700;color:#10233f;'>Username</td><td>${username}</td></tr><tr><td style='padding-right:14px;font-weight:700;color:#10233f;'>Email</td><td>${escapeHtml(email)}</td></tr><tr><td style='padding-right:14px;font-weight:700;color:#10233f;'>Changed</td><td>${escapeHtml(changedAtSaudi)}</td></tr></table></td></tr></table><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='width:100%;margin:0;background:#fff3f1;border:1px solid #efc2bc;border-radius:12px;'><tr><td width='34' valign='top' style='padding:16px 0 16px 18px;color:#c9362b;font-size:20px;'>●</td><td style='padding:15px 18px 15px 8px;color:#6b3733;font-size:13px;line-height:1.65;'><strong style='color:#7d211a;'>Didn’t make this change?</strong><br>Contact your IT administrator immediately. For your security, Masar will never ask you to send your password by email.</td></tr></table></td></tr><tr><td style='padding:18px 30px;background:#f6f9fc;border-top:1px solid #e2e9f2;color:#7b8ba1;font-size:12px;line-height:1.5;text-align:center;'>Masar IT Support &nbsp;·&nbsp; Automated security notification</td></tr></table></td></tr></table></body></html>`;
return [{json:{email,subject:'Security notice: Your Masar password was changed',html}}];
